package br.com.itbn.sisdent.controller;
import br.com.itbn.sisdent.dto.*; import br.com.itbn.sisdent.service.*; import jakarta.validation.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/organizations/{organizationId}/practitioners") public class PractitionerController { private final PractitionerService service; public PractitionerController(PractitionerService s){service=s;} @GetMapping public List<PractitionerResponse> list(@PathVariable UUID organizationId){return service.list(organizationId);}@PostMapping public ResponseEntity<PractitionerResponse> create(@PathVariable UUID organizationId,@Valid @RequestBody PractitionerRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(organizationId,r));}@PutMapping("/{id}") public PractitionerResponse update(@PathVariable UUID organizationId,@PathVariable UUID id,@Valid @RequestBody PractitionerRequest r){return service.update(organizationId,id,r);}@DeleteMapping("/{id}") public ResponseEntity<Void> deactivate(@PathVariable UUID organizationId,@PathVariable UUID id){service.deactivate(organizationId,id);return ResponseEntity.noContent().build();}}
